[{"order":1,"type":"heading","text":"Deployment Scripts, Verification, and CI/CD Pipelines in Solidity"},{"order":2,"type":"paragraph","text":"Building production-grade smart contracts requires more than just writing secure Solidity code. You need robust deployment scripts, automated contract verification on block explorers, and reliable CI/CD pipelines to ensure seamless updates and immutable records. This tutorial explores how to build these workflows using Hardhat and GitHub Actions."},{"order":3,"type":"subheading","text":"1. Writing Robust Deployment Scripts"},{"order":4,"type":"paragraph","text":"Using Hardhat with JavaScript or TypeScript allows you to script deployments deterministically. It is crucial to log deployed addresses and handle constructor arguments properly."},{"order":5,"type":"code","text":"const { ethers } = require("hardhat");

async function main() {
  const [deployer] = await ethers.getSigners();
  console.log("Deploying contracts with the account:", deployer.address);

  const Token = await ethers.getContractFactory("MyToken");
  const token = await Token.deploy(1000000);

  await token.waitForDeployment();
  console.log("Token deployed to:", await token.getAddress());
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});"},{"order":6,"type":"subheading","text":"2. Automated Contract Verification"},{"order":7,"type":"paragraph","text":"Once a contract is deployed to a testnet or mainnet, verifying its source code on Etherscan or similar explorers builds trust and enables interaction directly through the UI. Hardhat provides built-in plugins for this."},{"order":8,"type":"code","text":"await hre.run("verify:verify", {
  address: tokenAddress,
  constructorArguments: [1000000],
});"},{"order":9,"type":"subheading","text":"3. Setting Up CI/CD Pipelines with GitHub Actions"},{"order":10,"type":"paragraph","text":"Continuous Integration ensures that every push or pull request runs your test suite automatically, preventing regressions. Below is an example configuration for a GitHub Actions workflow."},{"order":11,"type":"code","text":"name: Solidity CI/CD

on:
  push:
    branches: [ "main" ]
  pull_request:
    branches: [ "main" ]

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Use Node.js
        uses: actions/setup-node@v3
        with:
          node-version: "18"
      - name: Install dependencies
        run: npm ci
      - name: Run tests
        run: npx hardhat test"},{"order":12,"type":"subheading","text":"Summary and Best Practices"},{"order":13,"type":"bullet_point","text":"Always use environment variables for private keys and API endpoints using dotenv."},{"order":14,"type":"bullet_point","text":"Implement dry-run deployments on local networks like Hardhat Network before targeting public testnets."},{"order":15,"type":"bullet_point","text":"Keep verification tasks automated inside your deployment scripts to avoid manual errors."}]
